"use strict";
// A checker that answers a boolean, or a promise when it has to wait, and a
// clock that answers a number of ticks or a Date.
let asked = 0;
const answers = [true, false, Promise.resolve(1)];
const moments = [5, 0, new Date(0)];
exports.verdict = (i) => (asked++, answers[i]);
exports.moment = (i) => (asked++, moments[i]);
exports.last = { verdict: Promise.resolve(2), moment: new Date(86400000), plain: false };
exports.settled = true;
exports.epoch = new Date(0);
exports.asked = () => asked;
